<?php
require_once __DIR__ . '/admin.lib.php';
$config = loadAdminConfig();
startAdminSession($config['session_name']);
cleanupExpiredAdminSecurityState();
header('X-Robots-Tag: noindex, nofollow', true);
$successMessage = '';
if (isset($_GET['logged_in'])) $successMessage = 'Signed in successfully.';
elseif (isset($_GET['logged_out'])) $successMessage = 'You have been signed out.';
elseif (isset($_GET['request_sent'])) $successMessage = 'Your admin access request has been sent for approval.';
elseif (isset($_GET['reset_requested'])) $successMessage = 'If the admin account exists, a password reset approval request has been sent.';
elseif (isset($_GET['password_reset_complete'])) $successMessage = 'Your password has been reset successfully. Please sign in.';
$errorMessage = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = trim((string) ($_POST['action'] ?? ''));
    if (!validateAdminCsrfToken($_POST['csrf_token'] ?? '')) {
        recordAdminSecurityEvent('invalid_admin_csrf_token', array('action' => $action), $config);
        $errorMessage = 'Your session has expired. Please refresh the page and try again.';
    } elseif ($action === 'request_account') {
        try {
            $request = createAdminAccountRequest((string) ($_POST['name'] ?? ''), (string) ($_POST['email'] ?? ''), (string) ($_POST['password'] ?? ''), (string) ($_POST['password_confirmation'] ?? ''), $config);
            header('Location: ' . (!empty($request['status_url']) ? (string) $request['status_url'] : 'admin.php?request_sent=1')); exit;
        } catch (RuntimeException $exception) { $errorMessage = $exception->getMessage(); }
    } elseif ($action === 'request_password_reset') {
        createAdminPasswordResetRequest((string) ($_POST['email'] ?? ''), $config); header('Location: admin.php?reset_requested=1'); exit;
    } elseif ($action === 'login') {
        $authMode = getAdminAuthMode($config);
        if ($authMode === 'bootstrap') $errorMessage = 'Request the first admin account before signing in.';
        elseif ($authMode === 'accounts') {
            $submittedEmail = trim((string) ($_POST['email'] ?? ''));
            $submittedPassword = trim((string) ($_POST['password'] ?? ''));
            $account = authenticateAdminAccount($submittedEmail, $submittedPassword);
            if ($account === null) {
                recordAdminSecurityEvent('failed_admin_login', array('reason' => 'invalid_account_credentials', 'email' => normalizeAdminEmail($submittedEmail)), $config);
                $errorMessage = 'Invalid email or password.';
            } else { setAdminAuthenticated(true, $account); header('Location: admin.php?logged_in=1'); exit; }
        } elseif (!verifyAdminPassword(trim((string) ($_POST['password'] ?? '')), $config)) {
            recordAdminSecurityEvent('failed_admin_login', array('reason' => 'invalid_legacy_password'), $config);
            $errorMessage = 'Invalid admin password.';
        } else { setAdminAuthenticated(true, array('name' => 'Admin User', 'email' => '')); header('Location: admin.php?logged_in=1'); exit; }
    } elseif ($action === 'logout') { setAdminAuthenticated(false); header('Location: admin.php?logged_out=1'); exit; }
}
$authMode = getAdminAuthMode($config); $csrfToken = ensureAdminCsrfToken(); $isAuthenticated = isAdminAuthenticated(); $authenticatedUser = getAuthenticatedAdminUser();
$showSignIn = in_array($authMode, array('accounts', 'legacy'), true); $showPasswordReset = $authMode === 'accounts';
$currentView = 'request';
if (isset($_GET['view']) && $_GET['view'] === 'signin' && $showSignIn) $currentView = 'signin';
if (isset($_GET['view']) && $_GET['view'] === 'reset' && $showPasswordReset) $currentView = 'reset';
$currentView = $errorMessage !== '' && !$isAuthenticated ? (($showSignIn && (str_contains($errorMessage, 'Invalid') || str_contains($errorMessage, 'sign in'))) ? 'signin' : $currentView) : $currentView;
$requestCardSubtitle = $authMode === 'bootstrap' ? 'Request First Admin Account' : 'Request New Admin Account';
$requestCardDescription = $authMode === 'bootstrap' ? 'The first admin account will not be created immediately. Your request will be sent to ' . (string) $config['account_request_approver_email'] . ' for approve/reject review.' : 'Need access for another administrator? Submit the new account request here. It will still require approval from ' . (string) $config['account_request_approver_email'] . ' before the new admin can sign in.';
?>
