<?php if (!$isAuthenticated): ?><div class="row justify-content-center"><div class="col-lg-8"><div class="project-detail-panel admin-panel-card" data-aos="fade-up"><span class="section-subtitle"><?php echo adminEscape($currentView === 'signin' ? 'Sign In' : ($currentView === 'reset' ? 'Forgot Password' : $requestCardSubtitle)); ?></span><?php if ($currentView === 'request'): ?><h2 class="section-title mb-3">Send admin account request</h2><p class="section-description mb-4"><?php echo adminEscape($requestCardDescription); ?></p><form method="POST" class="admin-form"><input type="hidden" name="action" value="request_account"><input type="hidden" name="csrf_token" value="<?php echo adminEscape($csrfToken); ?>"><div class="modern-form-group"><input class="modern-form-control" type="text" id="adminName" name="name" placeholder=" " required><label class="modern-form-label" for="adminName">Full Name</label><span class="modern-form-line"></span></div><div class="modern-form-group"><input class="modern-form-control" type="email" id="adminEmail" name="email" placeholder=" " required><label class="modern-form-label" for="adminEmail">Email Address</label><span class="modern-form-line"></span></div><div class="row"><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="password" id="adminPassword" name="password" placeholder=" " required><label class="modern-form-label" for="adminPassword">Password</label><span class="modern-form-line"></span></div></div><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="password" id="adminPasswordConfirm" name="password_confirmation" placeholder=" " required><label class="modern-form-label" for="adminPasswordConfirm">Confirm Password</label><span class="modern-form-line"></span></div></div></div><div class="admin-form-actions"><button type="submit" class="modern-submit-btn"><span class="btn-text">Send Request</span><span class="btn-icon"><i class="fas fa-paper-plane"></i></span></button><a href="index.html" class="btn btn-outline-primary">Back to Website</a></div><div class="d-flex flex-wrap gap-3 mt-4"><?php if ($showSignIn): ?><a href="admin.php?view=signin" class="btn btn-sm btn-outline-dark">Already have an account? Sign In</a><?php else: ?><span class="btn btn-sm btn-outline-secondary disabled">Sign In becomes available after approval</span><?php endif; ?></div></form><?php endif; ?><?php if ($currentView === 'signin'): ?><h2 class="section-title mb-3">Sign in to continue</h2><p class="section-description mb-4">Only authorized administrators can access article publishing and testimonial management.</p><form method="POST" class="admin-form"><input type="hidden" name="action" value="login"><input type="hidden" name="csrf_token" value="<?php echo adminEscape($csrfToken); ?>"><?php if ($authMode === 'accounts'): ?><div class="modern-form-group"><input class="modern-form-control" type="email" id="adminLoginEmail" name="email" placeholder=" " required><label class="modern-form-label" for="adminLoginEmail">Email Address</label><span class="modern-form-line"></span></div><?php endif; ?><div class="modern-form-group"><input class="modern-form-control" type="password" id="adminLoginPassword" name="password" placeholder=" " required><label class="modern-form-label" for="adminLoginPassword"><?php echo $authMode === 'accounts' ? 'Password' : 'Admin Password'; ?></label><span class="modern-form-line"></span></div><div class="admin-form-actions"><button type="submit" class="modern-submit-btn"><span class="btn-text">Sign In</span><span class="btn-icon"><i class="fas fa-lock"></i></span></button><a href="admin.php" class="btn btn-outline-primary">Back to Request</a></div><div class="d-flex flex-wrap gap-3 mt-4"><?php if ($showPasswordReset): ?><a href="admin.php?view=reset" class="btn btn-sm btn-outline-dark">Forgot password?</a><?php endif; ?></div></form><?php endif; ?><?php if ($currentView === 'reset'): ?><h2 class="section-title mb-3">Request password reset approval</h2><p class="section-description mb-4">Reset requests are not immediate. They are sent to <?php echo adminEscape((string) $config['password_reset_approver_email']); ?> for approval first.</p><form method="POST" class="admin-form"><input type="hidden" name="action" value="request_password_reset"><input type="hidden" name="csrf_token" value="<?php echo adminEscape($csrfToken); ?>"><div class="modern-form-group"><input class="modern-form-control" type="email" id="adminResetEmail" name="email" placeholder=" " required><label class="modern-form-label" for="adminResetEmail">Email Address</label><span class="modern-form-line"></span></div><div class="admin-form-actions"><button type="submit" class="btn btn-outline-primary">Request Reset Approval</button><a href="admin.php?view=signin" class="btn btn-outline-dark">Back to Sign In</a></div></form><?php endif; ?></div></div></div>
<?php else: ?><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3 mb-4"><div><span class="section-subtitle">Authenticated Session</span><h2 class="section-title mb-2">Protected Admin Workspace</h2><p class="section-description mb-0">Signed in as <?php echo adminEscape((string) ($authenticatedUser['name'] ?? 'Admin User')); ?><?php if (!empty($authenticatedUser['email'])): ?> (<?php echo adminEscape((string) $authenticatedUser['email']); ?>)<?php endif; ?>.</p></div><form method="POST"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf_token" value="<?php echo adminEscape($csrfToken); ?>"><button type="submit" class="btn btn-outline-danger"><i class="fas fa-right-from-bracket me-2"></i>Sign Out</button></form></div><div class="row g-5 align-items-start"><div class="col-lg-6"><div class="project-detail-panel admin-panel-card" data-aos="fade-up"><span class="section-subtitle">Article Editor</span><h2 class="section-title mb-3">Publish or Update Articles</h2><p class="section-description mb-4">Fill in the article details below. Just paste the article content normally — headings, paragraphs, lists, and accordion formatting are handled automatically after saving.</p><form id="adminArticleForm" class="admin-form"><input type="hidden" id="articleOriginalSlug" name="original_slug"><input type="hidden" id="adminCsrfToken" name="csrf_token" value="<?php echo adminEscape($csrfToken); ?>"><div class="modern-form-group"><input class="modern-form-control" type="text" id="articleTitleInput" name="title" placeholder=" " required><label class="modern-form-label" for="articleTitleInput">Article Title</label><span class="modern-form-line"></span></div><div class="row"><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="text" id="articleCategoryInput" name="category" placeholder=" " required><label class="modern-form-label" for="articleCategoryInput">Category</label><span class="modern-form-line"></span></div></div><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="text" id="articleTopicInput" name="topic" placeholder=" "><label class="modern-form-label" for="articleTopicInput">Topic / Slug Group</label><span class="modern-form-line"></span></div></div></div><div class="row"><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="date" id="articleDateInput" name="date" placeholder=" " required><label class="modern-form-label" for="articleDateInput">Publish Date</label><span class="modern-form-line"></span></div></div><div class="col-md-6"><div class="modern-form-group"><input class="modern-form-control" type="text" id="articleReadTimeInput" name="readTime" placeholder=" " value="5 min read"><label class="modern-form-label" for="articleReadTimeInput">Read Time</label><span class="modern-form-line"></span></div></div></div><div class="modern-form-group"><input class="modern-form-control" type="text" id="articleImageInput" name="image" placeholder=" "><label class="modern-form-label" for="articleImageInput">Image Path</label><span class="modern-form-line"></span></div><div class="modern-form-group"><textarea class="modern-form-control" id="articleExcerptInput" name="excerpt" placeholder=" "></textarea><label class="modern-form-label" for="articleExcerptInput">Brief Description (optional)</label><span class="modern-form-line"></span></div><div class="modern-form-group"><textarea class="modern-form-control admin-content-textarea" id="articleBodyInput" name="body" placeholder=" " required></textarea><label class="modern-form-label" for="articleBodyInput">Paste Article Content</label><span class="modern-form-line"></span><small class="form-text text-muted d-block mt-2">No HTML is needed. Paste normal text with section titles on their own lines and use -, *, or • for bullet points. The site will format the article and its accordion layout automatically.</small></div><div id="adminArticleMessage" class="mt-3" role="status" aria-live="polite"></div><div class="admin-form-actions"><button type="submit" class="modern-submit-btn"><span class="btn-text">Save Article</span><span class="btn-icon"><i class="fas fa-save"></i></span></button><button type="button" id="adminArticleReset" class="btn btn-outline-primary">Clear Form</button></div></form></div></div><div class="col-lg-6"><div class="project-detail-panel admin-panel-card mb-4" data-aos="fade-up" data-aos-delay="100"><span class="section-subtitle">Existing Articles</span><h2 class="section-title mb-3">Manage Published Articles</h2><div id="adminArticleList" class="admin-list-stack"></div></div><div class="project-detail-panel admin-panel-card" data-aos="fade-up" data-aos-delay="150"><span class="section-subtitle">Testimonials</span><h2 class="section-title mb-3">Delete Testimonials</h2><p class="section-description mb-4">Remove testimonials that should no longer appear publicly.</p><div id="adminTestimonialList" class="admin-list-stack"></div></div></div></div><?php endif; ?></div></section>
